-- FASE 1: DROP (cascade para respeitar FKs) - tabelas novas, esperado erro 'table not found' na 1a execucao, usar Skip All
DROP TABLE INDUSTRIAL_DATA.STOCK_BALANCE CASCADE;
DROP TABLE INDUSTRIAL_DATA.GOODS_RECEIPT_ITEM CASCADE;
DROP TABLE INDUSTRIAL_DATA.GOODS_RECEIPT CASCADE;
DROP TABLE INDUSTRIAL_DATA.MOVEMENT_TYPE CASCADE;

-- FASE 2: CREATE CONFIG TABLE
CREATE TABLE INDUSTRIAL_DATA.MOVEMENT_TYPE (MOVEMENT_TYPE_CODE NVARCHAR(3) NOT NULL PRIMARY KEY, MOVEMENT_TYPE_TEXT NVARCHAR(60) NOT NULL);

-- FASE 3: LOAD CONFIG DATA

-- FASE 4: CREATE GOODS RECEIPT HEADER + ITEM + STOCK BALANCE
CREATE TABLE INDUSTRIAL_DATA.GOODS_RECEIPT (
  GR_ID NVARCHAR(10) NOT NULL PRIMARY KEY,
  EBELN NVARCHAR(10) NOT NULL,
  WERKS NVARCHAR(4) NOT NULL,
  MOVEMENT_TYPE_CODE NVARCHAR(3) NOT NULL,
  GR_DATE DATE NOT NULL,
  FOREIGN KEY (EBELN) REFERENCES INDUSTRIAL_DATA.PURCHASE_ORDER(EBELN),
  FOREIGN KEY (WERKS) REFERENCES INDUSTRIAL_DATA.PLANT(WERKS),
  FOREIGN KEY (MOVEMENT_TYPE_CODE) REFERENCES INDUSTRIAL_DATA.MOVEMENT_TYPE(MOVEMENT_TYPE_CODE)
);

CREATE TABLE INDUSTRIAL_DATA.GOODS_RECEIPT_ITEM (
  GR_ITEM_ID INT NOT NULL PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
  GR_ID NVARCHAR(10) NOT NULL,
  PO_ITEM_NO INT NOT NULL,
  MATNR NVARCHAR(10) NOT NULL,
  WERKS NVARCHAR(4) NOT NULL,
  QUANTITY_ORDERED DECIMAL(15, 2) NOT NULL,
  QUANTITY_RECEIVED DECIMAL(15, 2) NOT NULL,
  RECEIPT_PCT DECIMAL(5, 2) NOT NULL,
  BATCH_NO NVARCHAR(20),
  FOREIGN KEY (GR_ID) REFERENCES INDUSTRIAL_DATA.GOODS_RECEIPT(GR_ID),
  FOREIGN KEY (MATNR) REFERENCES INDUSTRIAL_DATA.MATERIAL(MATNR),
  FOREIGN KEY (WERKS) REFERENCES INDUSTRIAL_DATA.PLANT(WERKS),
  CHECK (QUANTITY_RECEIVED >= 0),
  CHECK (RECEIPT_PCT > 0 AND RECEIPT_PCT <= 100)
);

CREATE TABLE INDUSTRIAL_DATA.STOCK_BALANCE (
  STOCK_ID INT NOT NULL PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
  MATNR NVARCHAR(10) NOT NULL,
  WERKS NVARCHAR(4) NOT NULL,
  QUANTITY_ON_HAND DECIMAL(15, 2) NOT NULL,
  LAST_UPDATED DATE,
  FOREIGN KEY (MATNR) REFERENCES INDUSTRIAL_DATA.MATERIAL(MATNR),
  FOREIGN KEY (WERKS) REFERENCES INDUSTRIAL_DATA.PLANT(WERKS),
  CHECK (QUANTITY_ON_HAND >= 0)
);

