SELECT RECEIPT_PCT, COUNT(*) FROM INDUSTRIAL_DATA.GOODS_RECEIPT_ITEM GROUP BY RECEIPT_PCT ORDER BY RECEIPT_PCT;
SELECT TOP 5 MATNR, WERKS, QUANTITY_ON_HAND FROM INDUSTRIAL_DATA.STOCK_BALANCE ORDER BY QUANTITY_ON_HAND DESC;
